parameters.jsCode:
const MONTHS = { jan:1, feb:2, mar:3, apr:4, may:5, jun:6, jul:7, aug:8, sep:9, oct:10, nov:11, dec:12 };
const pad = n => String(n).padStart(2, '0');

// "  rahul   SHARMA " -> "Rahul Sharma"
const properCase = v => String(v ?? '')
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim()
  .replace(/(^|[\s'\-])([a-z])/g, (m, sep, ch) => sep + ch.toUpperCase());

// keep only 0-9; drop a leading +91 country code
const digitsOnly = v => {
  let d = String(v ?? '').replace(/\D/g, '');
  if (d.length === 12 && d.startsWith('91')) d = d.slice(2);
  return d;
};

// "34 yrs" -> "34"
const ageDigits = v => String(v ?? '').replace(/\D/g, '');

// many input formats -> dd-mm-yyyy
const toDDMMYYYY = v => {
  v = String(v ?? '').trim();
  if (!v) return '';
  let d, m, y, x;
  if ((x = v.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})$/))) { y = +x[1]; m = +x[2]; d = +x[3]; }
  else if ((x = v.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})$/))) { d = +x[1]; m = +x[2]; y = +x[3]; }
  else if ((x = v.match(/^(\d{1,2})[-\/. ]([A-Za-z]{3,9})[-\/. ,]*(\d{4})$/))) { d = +x[1]; m = MONTHS[x[2].slice(0, 3).toLowerCase()]; y = +x[3]; }
  else return v;                       // unrecognised -> leave as is
  if (!m || m > 12 || d > 31) return v;
  return pad(d) + '-' + pad(m) + '-' + y;
};

return $input.all().map(item => {
  const j = item.json;
  return { json: {
    'Customer Name': properCase(j['Customer Name']),
    'Contact Number': digitsOnly(j['Contact Number']),
    'Age': ageDigits(j['Age']),
    'Date of Purchase': toDDMMYYYY(j['Date of Purchase']),
    'Shipping Date': toDDMMYYYY(j['Shipping Date']),
    'Delivery Date': toDDMMYYYY(j['Delivery Date']),
  }};
});

// dates arrive as dd-mm-yyyy text
const parse = s => {
  const m = String(s ?? '').match(/^(\d{2})-(\d{2})-(\d{4})$/);
  return m ? new Date(Date.UTC(+m[3], +m[2] - 1, +m[1])) : null;
};

return $input.all().map(item => {
  const j = item.json;
  const p = parse(j['Date of Purchase']);
  const s = parse(j['Shipping Date']);
  const d = parse(j['Delivery Date']);
  const flags = [];
  if (s && d && s > d) flags.push('Shipping date is after delivery date');
  if (p && d && d < p) flags.push('Delivery date is before purchase date');
  if (!p || !s || !d) flags.push('Missing date');
  return { json: { ...j, 'Date Flag': flags.length ? 'FLAG: ' + flags.join('; ') : 'OK' } };
});

// replace empty / missing cells with NA
return $input.all().map(item => ({
  json: Object.fromEntries(
    Object.entries(item.json).map(([k, v]) => [k, (v === null || v === undefined || String(v).trim() === '') ? 'NA' : v])
  )
}));

return $input.all().map(item => ({
  json: Object.fromEntries(
    Object.entries(item.json).map(([k, v]) => [k.toUpperCase(), v])
  )
}));

